{"operation":"run_python","code":"def g0(x):
    return x + abs(x - 200) - abs(x + 200)

def count_solutions(n):
    # We want to find number of x such that gn(x) = 0
    # Instead of iterating x, we can iterate backwards from 0 to find Sn
    S = {0}
    for _ in range(n):
        new_S = set()
        for y in S:
            # |z| - 1 = y => |z| = y + 1
            if y + 1 >= 0:
                new_S.add(y + 1)
                new_S.add(-(y + 1))
        S = new_S

    count = 0
    for y in S:
        # Count solutions to g0(x) = y
        # x - 400 = y => x = y + 400 (valid if x >= 200 => y >= -200)
        if y >= -200:
            count += 1
        # -x = y => x = -y (valid if -200 <= x < 200 => -200 < y <= 200)
        if y > -200 and y <= 200:
            count += 1
        # x + 400 = y => x = y - 400 (valid if x < -200 => y < 200)
        if y < 200:
            count += 1
    return count, len(S), S

print("n=1:", count_solutions(1))
print("n=2:", count_solutions(2))
