    from itertools import permutations

    def is_valid(n):
        s = str(n)
        digits = [int(d) for d in s]
        if 0 in digits:
            return False
        for d in digits:
            if n % (d * d) != 0:
                return False
        return True

    candidates = []
    for p in permutations(range(1, 10), 4):
        n = int(''.join(map(str, p)))
        if is_valid(n):
            candidates.append(n)

    candidates.sort()
    return candidates[0] if candidates else None

