def check_ssa(a, b, A_deg):
    A = math.radians(A_deg)
    sin_B = (b * math.sin(A)) / a
    if sin_B > 1:
        return "No solution"
    elif abs(sin_B - 1) < 1e-9:
        return "One solution (right triangle)"
    else:
        B1 = math.degrees(math.asin(sin_B))
        B2 = 180 - B1
        solutions = []
        if A + B1 < 180:
            solutions.append(B1)
        if A + B2 < 180 and abs(B1 - B2) > 1e-9:
            solutions.append(B2)
        return f"One solution" if len(solutions) == 1 else "Two solutions"

